"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["98172"],{95267(e){e.exports=JSON.parse('{"id":"FIN-1432","slug":"asset-heavy-business","term":"Asset-Heavy Business","also_known_as":[],"difficulty":"Advanced","definition":"An asset-heavy business is a company that needs large amounts of physical assets, such as factories, equipment, property, vehicles or infrastructure, to operate and grow.","explanation":["Asset-heavy businesses own most of the physical assets they use to deliver their products or services. Examples include utilities, airlines that own their aircraft, steel producers, telecoms networks, railways, hotel companies that own their buildings and manufacturers.","These businesses typically have high fixed costs, large capital expenditure needs and high operating leverage, so their profits are sensitive to changes in demand. Growing usually requires heavy investment, which can limit free cash flow.","For example, a hotel company that owns its properties must spend heavily on buying and maintaining buildings, while an asset-light hotel company that franchises its brand to property owners can expand with little capital.","Asset-heavy models also have advantages. They give companies control over quality and operations, create barriers to entry for competitors and provide valuable assets that can be used as collateral for borrowing. Investors often compare asset-heavy businesses using measures such as return on invested capital and capital intensity."],"note":"","total":1500,"prev":{"slug":"asset-based-valuation","term":"Asset-Based Valuation"},"next":{"slug":"asset-light-business","term":"Asset-Light Business"}}')}}]);